(function(root){'use strict';
function cdf(x){const a=Math.abs(x),t=1/(1+.2316419*a),v=1-Math.exp(-a*a/2)/Math.sqrt(2*Math.PI)*t*(.319381530+t*(-.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return x>=0?v:1-v;}
function option(s,k,days,iv,type){const t=Math.max(days,1/1440)/365,r=.06,d1=(Math.log(s/k)+(r+iv*iv/2)*t)/(iv*Math.sqrt(t)),d2=d1-iv*Math.sqrt(t),p=Math.exp(-d1*d1/2)/Math.sqrt(2*Math.PI),disc=Math.exp(-r*t);return{price:Math.max(0,type==='CE'?s*cdf(d1)-k*disc*cdf(d2):k*disc*cdf(-d2)-s*cdf(-d1)),delta:type==='CE'?cdf(d1):cdf(d1)-1,gamma:p/(s*iv*Math.sqrt(t)),vega:s*p*Math.sqrt(t)/100,theta:(-s*p*iv/(2*Math.sqrt(t))+(type==='CE'?-r*k*disc*cdf(d2):r*k*disc*cdf(-d2)))/365};}
function aggregate(positions,mark){let realized=0,unrealized=0,lots=0;for(const p of positions){const pnl=((p.closed?p.exit:mark(p))-p.atp)*p.lots*p.lotSize*p.side;if(p.closed)realized+=pnl;else{unrealized+=pnl;lots+=p.lots;}}return{realized,unrealized,total:realized+unrealized,lots};}
function add(positions,order){const p=positions.find(p=>!p.closed&&p.key===order.key&&p.side===order.side);if(p){p.atp=(p.atp*p.lots+order.price*order.lots)/(p.lots+order.lots);p.lots+=order.lots;return p;}const next={...order,atp:order.price,closed:false};positions.push(next);return next;}
function candles(points,interval){const result=[];for(const p of points){const bucket=Math.floor(p.t/(interval*60000))*interval*60000;let c=result.at(-1);if(!c||c.t!==bucket){c={t:bucket,o:p.price,h:p.price,l:p.price,c:p.price};result.push(c);}else{c.h=Math.max(c.h,p.price);c.l=Math.min(c.l,p.price);c.c=p.price;}}return result;}
const api={option,aggregate,add,candles};if(typeof module!=='undefined')module.exports=api;else root.DeskEngine=api;
})(typeof window!=='undefined'?window:globalThis);
